-- Day 13: short beginner-friendly descriptions for the Bird Profile page (shown under the listen button).
-- Step 1: make sure the column can hold a full paragraph. Safe to run even if it is already TEXT.
ALTER TABLE birds MODIFY COLUMN description TEXT NULL;

-- Step 2: fill the descriptions. Each bird is matched by latin_name, which is unique.
-- Note: inside a SQL string, an apostrophe is written twice ('') so it doesn't end the string.
START TRANSACTION;
UPDATE birds SET description = 'A big brown goose with a black head and neck and a white "chinstrap". Males and females look alike, though males run a little larger. Look for them on lakes, parks, golf courses, and farm fields. Their loud honking often announces a V-shaped flock overhead before you see it. Pairs usually stay together for life and fiercely defend their fuzzy yellow goslings.' WHERE latin_name = 'Branta canadensis';  -- Canada Goose
UPDATE birds SET description = 'The classic duck of ponds and parks. Males have a glossy green head, white neck ring, and chestnut chest. Females are mottled brown with an orange-and-black bill. Both show a blue wing patch edged in white. Their hallmark "quack" comes from the female; males make a quieter, raspy sound. Most farmyard ducks are descended from Mallards.' WHERE latin_name = 'Anas platyrhynchos';  -- Mallard
UPDATE birds SET description = 'One of North America''s largest birds, with a wingspan near 9 feet. It is bright white with a huge orange bill and pouch, and black wing edges that show in flight. Sexes look alike. Find it on lakes and marshes; Gunnison Island in the Great Salt Lake hosts a major nesting colony. Instead of diving, groups swim together and scoop up fish.' WHERE latin_name = 'Pelecanus erythrorhynchos';  -- American White Pelican
UPDATE birds SET description = 'A shorebird that often lives nowhere near the shore. It is brown above and white below, with two black bands across the chest and an orange rump that shows in flight. Sexes look alike. Look in fields, ballparks, and gravel lots. To lure predators away from its nest, it drags a wing as if broken. Its name comes from its piercing "kill-deer" call.' WHERE latin_name = 'Charadrius vociferus';  -- Killdeer
UPDATE birds SET description = 'Utah''s state bird. Adults have a white head and body, gray back, black wingtips, and greenish-yellow legs. The yellow bill has both a red and a black spot near the tip. Sexes look alike; young birds are mottled brown. Find them at lakes, farm fields, and parking lots. In 1848, gulls were credited with saving Utah pioneers'' crops by eating swarms of crickets.' WHERE latin_name = 'Larus californicus';  -- California Gull
UPDATE birds SET description = 'A medium-sized gull named for an easy clue: a black ring around its yellow bill. Adults are white with a pale gray back, black wingtips, and yellow legs. Sexes look alike, while young birds are speckled brown and take about three years to reach adult colors. Look at lakes, rivers, and parking lots, where these bold birds gladly grab dropped french fries.' WHERE latin_name = 'Larus delawarensis';  -- Ring-billed Gull
UPDATE birds SET description = 'A large, dark soaring bird with a small, bare red head. From below, its wings look two-toned: black in front, silvery in back. It holds them in a shallow V and teeters side to side. Sexes look alike. Watch for it over roads, canyons, and open country. Unlike most birds, it has a keen sense of smell, which it uses to find carrion (dead animals).' WHERE latin_name = 'Cathartes aura';  -- Turkey Vulture
UPDATE birds SET description = 'A stocky, broad-winged hawk, often seen perched on roadside poles. It is brown above and pale below, usually with a band of dark streaks across the belly. Adults have a brick-red tail. Females are larger than males but colored the same. Look over open country, foothills, and highways. Its raspy scream is the "eagle" cry you often hear in movies.' WHERE latin_name = 'Buteo jamaicensis';  -- Red-tailed Hawk
UPDATE birds SET description = 'The familiar city pigeon. It is plump and small-headed, usually gray with two black wing bars and a shimmering green-and-purple neck, though white, brown, and patchwork birds are common. Sexes look similar, but males puff up and strut. Originally cliff dwellers, they now use bridges and buildings. They came from Europe in the 1600s, and their homing skills once carried wartime messages.' WHERE latin_name = 'Columba livia';  -- Rock Pigeon
UPDATE birds SET description = 'A slim, soft-tan bird with a small head, black wing spots, and a long, pointed tail. Males and females look very similar, though males have a slightly rosier chest. Look on wires, lawns, and open fields. Its sad-sounding "coo-OO-oo, oo, oo" gives it its name and is often mistaken for an owl. Its wings make a whistling sound on takeoff.' WHERE latin_name = 'Zenaida macroura';  -- Mourning Dove
UPDATE birds SET description = 'A tiny hummingbird, metallic green above and pale below. Males have a black throat with a thin band of violet at the bottom that flashes in good light. Females have a plain whitish throat. Look in canyons, along streams, and at backyard feeders. It pumps its tail constantly while hovering. Its nest is held together with spider silk, which stretches as the chicks grow.' WHERE latin_name = 'Archilochus alexandri';  -- Black-chinned Hummingbird
UPDATE birds SET description = 'A stocky, slate-blue bird with a shaggy crest and an oversized bill. Males have one blue band across a white chest. Females add a second, rusty band, making them the more colorful sex, which is unusual among birds. Look along streams and lakes for one perched over the water. It dives headfirst for fish, gives a loud rattling call, and nests in burrows dug into dirt banks.' WHERE latin_name = 'Megaceryle alcyon';  -- Belted Kingfisher
UPDATE birds SET description = 'North America''s smallest woodpecker. It has checkered black-and-white wings, a white stripe down its back, and a tiny bill. Males have a small red spot on the back of the head; females do not. Look in woods, parks, and at suet feeders. The nearly identical Hairy Woodpecker is larger, with a bill about as long as its head. A Downy''s bill is much shorter.' WHERE latin_name = 'Dryobates pubescens';  -- Downy Woodpecker
UPDATE birds SET description = 'A large brown woodpecker with a barred back, spotted belly, and a black crescent on its chest. In Utah, its wings and tail flash salmon-red in flight, along with a white rump. Males have a red "mustache" stripe; females do not. Look in woods, parks, and on lawns, where it digs for ants. Listen for a loud "wick-wick-wick" and drumming on metal chimneys.' WHERE latin_name = 'Colaptes auratus';  -- Northern Flicker
UPDATE birds SET description = 'A large flycatcher with a gray head, pale chest, lemon-yellow belly, and a dark tail edged in white. Sexes look alike. Look on wires and fences in open country, farms, and places with scattered trees. It darts out from a perch to catch insects in midair. True to its "king" name, it boldly chases hawks and ravens that come too close.' WHERE latin_name = 'Tyrannus verticalis';  -- Western Kingbird
UPDATE birds SET description = 'A striking jay with a charcoal-black head, a tall shaggy crest, and a deep blue body. Utah birds also show small white marks above the eye. Sexes look alike. Find it in evergreen mountain forests, where it boldly visits campgrounds and picnic tables. It can mimic the screams of hawks. It is named for Georg Steller, a naturalist on a 1741 Alaskan expedition.' WHERE latin_name = 'Cyanocitta stelleri';  -- Steller's Jay
UPDATE birds SET description = 'A slim, long-tailed jay with a blue head, wings, and tail, a gray back, and pale underparts with a faint blue necklace. Unlike a Steller''s Jay, it has no crest. Sexes look alike. Look in scrub oak, pinyon and juniper foothills, and backyards along the Wasatch. Listen for a harsh "shreep". It buries thousands of acorns and pinyon seeds to eat later.' WHERE latin_name = 'Aphelocoma woodhouseii';  -- Woodhouse's Scrub-Jay
UPDATE birds SET description = 'Unmistakable in black and white, with a very long tail and wings that shine blue-green in the sun. Sexes look alike, though males are a bit larger. Look in open country, farms, and towns, and for its huge domed stick nests in trees. A clever relative of crows, it can be bold: Lewis and Clark reported magpies stealing food right out of their tents.' WHERE latin_name = 'Pica hudsonia';  -- Black-billed Magpie
UPDATE birds SET description = 'All black, from bill to feet, with a slight sheen. Sexes look alike. Look almost anywhere: fields, parks, and towns. To tell it from a raven, listen for the familiar "caw" and look for a fan-shaped tail. Crows are very smart and can remember individual human faces. Young birds often stay with their parents to help raise the next brood.' WHERE latin_name = 'Corvus brachyrhynchos';  -- American Crow
UPDATE birds SET description = 'A huge all-black bird with a thick bill and shaggy throat feathers. Sexes look alike. Look over deserts, mountains, canyons, and roadsides. To tell it from a crow, listen for a deep, croaking "gronk" and look for a wedge-shaped tail in flight. Among the smartest of all birds, ravens solve puzzles and are often seen doing rolls and tumbles in the air, seemingly for fun.' WHERE latin_name = 'Corvus corax';  -- Common Raven
UPDATE birds SET description = 'A stocky, short-tailed jay that is dusty blue all over, with a paler throat and no crest. Its long, pointed bill makes it look a bit like a small blue crow. Sexes look alike. Find it in pinyon and juniper woodlands, usually in noisy, laughing flocks that can number in the hundreds. It buries thousands of pinyon seeds, and forgotten ones can grow into new trees.' WHERE latin_name = 'Gymnorhinus cyanocephalus';  -- Pinyon Jay
UPDATE birds SET description = 'A tiny, round-bodied bird with a black cap and bib, white cheeks, a gray back, and buffy (tan) sides. Sexes look alike. Look in streamside woods, canyons, and at backyard feeders. It calls its own name: "chick-a-dee-dee-dee". The more "dee" notes it adds, the bigger the threat it has spotted. Its song, on the other hand, is a sweet, two-note "fee-bee" or "hey, sweetie".' WHERE latin_name = 'Poecile atricapillus';  -- Black-capped Chickadee
UPDATE birds SET description = 'Looks much like a Black-capped Chickadee, but a white stripe cuts through its black cap above the eye, like an eyebrow. Its sides are gray rather than tan. Sexes look alike. Find it in evergreen mountain forests, and at lower feeders in winter. Its "chick-a-dee" sounds more raspy than a Black-capped''s, and its song is often described as a 3-note whistle of "cheese-bur-ger". It stores seeds in bark for winter.' WHERE latin_name = 'Poecile gambeli';  -- Mountain Chickadee
UPDATE birds SET description = 'A slender brown ground bird with a pale yellow face, a black mask, and a black band across its chest. Two tiny black feather tufts can stick up like horns. Females are more drab, with smaller horns. Look on bare ground: fields, desert flats, and high mountain tundra. It walks rather than hops, and males sing a tinkling song while flying high overhead.' WHERE latin_name = 'Eremophila alpestris';  -- Horned Lark
UPDATE birds SET description = 'A sleek swallow, glossy blue-green above and snowy white below. Females are slightly more drab, and young females can look mostly brown above. Look near water and open fields, where it swoops after flying insects. It nests in old woodpecker holes and nest boxes, which makes it easy to attract. It lines its nest with feathers collected from other birds.' WHERE latin_name = 'Tachycineta bicolor';  -- Tree Swallow
UPDATE birds SET description = 'A small swallow with a green back, violet rump, and bright white underparts. White on its face reaches above the eye, and white patches on the sides nearly meet over the rump. Those clues separate it from a Tree Swallow. Females are more drab, with a darker face. Look in mountain canyons and forests, where it nests in tree holes and cliff cracks.' WHERE latin_name = 'Tachycineta thalassina';  -- Violet-green Swallow
UPDATE birds SET description = 'A plain swallow, brown above and pale below, with a dusky throat. Sexes look alike. Look over rivers, banks, and near road cuts, where it nests in burrows, often ones dug by other animals. The name comes from a feature you would never see from afar: males have tiny hooks along the edge of the outer wing feather, making it feel rough.' WHERE latin_name = 'Stelgidopteryx serripennis';  -- Northern Rough-winged Swallow
UPDATE birds SET description = 'A graceful swallow with a deep blue back, a rusty throat, and a long, deeply forked tail. Males have richer orange underparts and longer tail streamers; females are paler. Look over fields and water, and around farms and bridges. It builds a cup-shaped mud nest under eaves and inside barns. It is the most widespread swallow in the world.' WHERE latin_name = 'Hirundo rustica';  -- Barn Swallow
UPDATE birds SET description = 'A stocky swallow with a square tail, a pale forehead, a dark rusty throat, and a tan rump that stands out in flight. Sexes look alike. Look near water, cliffs, bridges, and dams, where colonies build gourd-shaped nests from thousands of mud pellets. These are the famous swallows said to return each spring to the mission at San Juan Capistrano, California.' WHERE latin_name = 'Petrochelidon pyrrhonota';  -- Cliff Swallow
UPDATE birds SET description = 'A tiny olive-green bird with a white eye ring and one bold white wing bar, always flicking its wings. Males have a ruby-red crown patch, usually hidden until they get excited. Females lack the namesake crown. Look in evergreen forests in summer and in lower woods and yards during migration. Its song is surprisingly loud for such a small bird, and it can lay up to 12 eggs.' WHERE latin_name = 'Corthylio calendula';  -- Ruby-crowned Kinglet
UPDATE birds SET description = 'A small, compact bird with a blue-gray back, rusty underparts, a black eye stripe, and a white eyebrow. Males have a black cap and deeper color; females have a grayer cap and paler belly. Look in evergreen forests and at feeders, creeping headfirst down tree trunks. Its nasal "yank-yank" sounds like a tiny tin horn. It smears sticky sap around its nest hole.' WHERE latin_name = 'Sitta canadensis';  -- Red-breasted Nuthatch
UPDATE birds SET description = 'A tiny, streaky brown bird so well camouflaged it looks like a moving piece of bark. It has a white belly, a thin curved bill, and a stiff tail used as a prop. Sexes look alike. Look in mature forests. It spirals up one trunk searching for insects, then flies down to the base of the next tree and starts again. It nests behind loose bark.' WHERE latin_name = 'Certhia americana';  -- Brown Creeper
UPDATE birds SET description = 'A tiny rusty-brown bird with a white eyebrow, a black-and-white streaked back, and a tail often held straight up. Sexes look alike. Find it in cattail marshes, more often heard than seen. Males sing a gurgling, rattling song, sometimes through the night. They also build several extra nests around their territory, possibly to impress females or confuse predators.' WHERE latin_name = 'Cistothorus palustris';  -- Marsh Wren
UPDATE birds SET description = 'A familiar songbird with a brick-orange breast, gray-brown back, dark head, and yellow bill. Females are paler than males. Look on lawns, in parks, and in mountain forests, running and stopping to hunt for worms. Its song sounds like "cheerily, cheer-up, cheerio". Colonists named it after the European robin for its orange chest, but it is actually a thrush, a different kind of bird.' WHERE latin_name = 'Turdus migratorius';  -- American Robin
UPDATE birds SET description = 'Males are entirely sky blue, slightly paler on the belly. Females are gray-brown with hints of blue on the wings and tail. Look in sagebrush, open country, and mountain meadows. It often hovers above the ground before dropping onto an insect, and it nests in old woodpecker holes and nest boxes. It is the state bird of both Idaho and Nevada.' WHERE latin_name = 'Sialia currucoides';  -- Mountain Bluebird
UPDATE birds SET description = 'A stocky, short-tailed bird. In summer it is glossy purple and green with a yellow bill; in winter it is covered in white spots. Sexes look similar, but the base of the bill is bluish in males and pinkish in females. Look on lawns and in cities and farmland. About 100 were released in New York''s Central Park in 1890 and 1891. Millions live here today.' WHERE latin_name = 'Sturnus vulgaris';  -- European Starling
UPDATE birds SET description = 'A silky brown bird with a crest, a black mask, a pale yellow belly, and a tail that looks dipped in yellow paint. Its wings have small red tips that resemble sealing wax, which gives it its name. Sexes look nearly alike. Look in flocks at berry trees, and listen for a thin, high "sreee". Flock members sometimes pass berries down the line, beak to beak.' WHERE latin_name = 'Bombycilla cedrorum';  -- Cedar Waxwing
UPDATE birds SET description = 'A chunky city bird. Males have a gray crown, chestnut neck, white cheeks, and a black bib. Females are plain tan-brown with a pale stripe behind the eye. Look around buildings, farms, and parking lots, usually close to people. Brought from Europe to Brooklyn in the early 1850s, it spread across the continent. Despite the name, it is not closely related to our native sparrows.' WHERE latin_name = 'Passer domesticus';  -- House Sparrow
UPDATE birds SET description = 'A tiny, slender bird, blue-gray above and white below, with a white eye ring and a long black tail edged in white. In breeding season, males have a thin black "V" on the forehead; females are grayer. Look in scrub oak and juniper, flicking its tail as it hunts. Listen for a thin, wheezy "spee". Its tiny nest is made of lichen and spider silk.' WHERE latin_name = 'Polioptila caerulea';  -- Blue-gray Gnatcatcher
UPDATE birds SET description = 'A small, streaky brown finch with a stubby bill. Males have a rosy-red head and chest, though it can range to orange or yellow depending on diet. Females are plain and streaky, with no face pattern. Look in towns, yards, and feeders. Once found only in the West, some released in New York around 1940 spread across the East. Its long, cheerful song often ends on a buzzy note.' WHERE latin_name = 'Haemorhous mexicanus';  -- House Finch
UPDATE birds SET description = 'A tiny, streaky brown finch with a sharply pointed bill and flashes of yellow in the wings and tail. Sexes look similar, though males tend to show more yellow. Look in evergreen forests and at thistle feeders, often in busy, chattering flocks. Learn its signature call, a rising "zzzreee" that sounds like someone zipping up a jacket. Numbers vary greatly from year to year.' WHERE latin_name = 'Spinus pinus';  -- Pine Siskin
UPDATE birds SET description = 'A tiny finch. Males have a black cap, a greenish back, bright yellow underparts, and white wing patches. Females are olive above and dull yellow below. Look in weedy fields, along streams, and at backyard feeders. Listen for a sad-sounding "tee-yee" call. Its rambling song often includes imitations of other birds'' calls, so what you hear may surprise you.' WHERE latin_name = 'Spinus psaltria';  -- Lesser Goldfinch
UPDATE birds SET description = 'In summer, males are lemon yellow with a black forehead and black wings, while females are more drab olive-yellow. In winter, both turn a plain brownish color. Look in weedy fields, along roads, and at thistle feeders. Its bouncy flight comes with a call that sounds like "po-ta-to-chip". It eats almost only seeds and nests late in summer, when thistles are ready.' WHERE latin_name = 'Spinus tristis';  -- American Goldfinch
UPDATE birds SET description = 'A compact bird with a blue-gray back, white face and belly, and a rusty patch under the tail. Males have a shiny black cap; females usually have a paler one. Look in mature trees and at feeders, climbing headfirst down trunks. Listen for a nasal "yank-yank". It wedges large seeds into bark and hacks them open, which is where the name "nuthatch" comes from.' WHERE latin_name = 'Sitta carolinensis';  -- White-breasted Nuthatch
UPDATE birds SET description = 'A stocky finch of high mountain forests. Males are washed in rosy pink, with a brighter red cap that stands out against the brown neck. Females are brown and white with crisp, dark streaks. Look in evergreens and at mountain feeders. It resembles a House Finch, but with a longer bill and neater markings. It often mimics other birds. It is named for naturalist John Cassin.' WHERE latin_name = 'Haemorhous cassinii';  -- Cassin's Finch
UPDATE birds SET description = 'A small, trim sparrow with a rusty cap, white eyebrow, black line through the eye, and plain gray chest. Sexes look alike, and both turn duller in winter. Look in open woods, parks, and yards. Its song is a long, dry trill on a single pitch, like a tiny sewing machine. Its small cup nest is often lined with animal hair.' WHERE latin_name = 'Spizella passerina';  -- Chipping Sparrow
UPDATE birds SET description = 'A neat sparrow with a dark hood, a pale pink bill, and a white belly. White outer tail feathers flash when it flies. Utah has several color forms, some with pinkish sides or a rusty back. Males are usually darker, females browner. It nests in mountain forests and moves down to backyards in winter, earning the nickname "snowbird".' WHERE latin_name = 'Junco hyemalis';  -- Dark-eyed Junco
UPDATE birds SET description = 'A handsome sparrow with bold black-and-white stripes on its head, a plain gray chest, and a pinkish-orange bill. Sexes look alike; young birds have brown and tan head stripes. Look in brushy edges and backyards in winter and mountain willows in summer. Males learn their whistled song when young, so birds in different areas sing with their own local "dialects".' WHERE latin_name = 'Zonotrichia leucophrys';  -- White-crowned Sparrow
UPDATE birds SET description = 'A streaky brown sparrow whose chest streaks often meet in a dark central spot. Sexes look alike. Look in brush, along streams, in marshes, and in yards, and watch for its long tail pumping as it flies. Its song starts with a few clear notes followed by a jumble, often remembered as "Maids, maids, maids, put on your tea kettle-ettle-ettle".' WHERE latin_name = 'Melospiza melodia';  -- Song Sparrow
UPDATE birds SET description = 'A large, striking sparrow with distinctive red eyes. Males have a black head and back dotted with white spots, rufous (rusty-red) sides, and a white belly. Females have the same pattern, but grayish brown replaces the black. Look in scrub oak and dense brush. Listen for leaves rustling as it hops backward with both feet to uncover food, and for its catlike "mew".' WHERE latin_name = 'Pipilo maculatus';  -- Spotted Towhee
UPDATE birds SET description = 'A large, chunky sparrow. Utah''s birds have a gray head and back, rusty wings and tail, and a heavily spotted chest. Sexes look alike. Look in mountain willow thickets and brush along streams. Like a towhee, it kicks backward with both feet to scratch up food, so listen for rustling leaves. The name comes from the fox-red color of many populations.' WHERE latin_name = 'Passerella iliaca';  -- Fox Sparrow
UPDATE birds SET description = 'Males are hard to miss: a black body, bright yellow head and chest, and white wing patches. Females are smaller and dusky brown, with a dull yellow throat and chest. Look in cattail marshes, especially around deep water, and in nearby fields. The male''s song is a harsh, strangled scrape, often compared to a rusty gate, and it is unlike anything else in the marsh.' WHERE latin_name = 'Xanthocephalus xanthocephalus';  -- Yellow-headed Blackbird
UPDATE birds SET description = 'A chunky bird with a mottled brown back, bright yellow underparts, and a black "V" on the chest. White outer tail feathers flash in flight. Sexes look similar, though females are slightly duller. Look on fence posts in grasslands, fields, and sagebrush. Its rich, flute-like song has made it the state bird of six states. Despite the name, it is a type of blackbird, not a lark.' WHERE latin_name = 'Sturnella neglecta';  -- Western Meadowlark
UPDATE birds SET description = 'Males are flame orange with a black eye line, black throat, and a big white wing patch. Females are yellowish with a gray back and pale belly. Look in cottonwoods along streams and in parks and yards. Its woven nest hangs like a soft pouch from a branch. It loves orange halves and jelly at feeders, and it is named for William Bullock, an English collector.' WHERE latin_name = 'Icterus bullockii';  -- Bullock's Oriole
UPDATE birds SET description = 'Males are glossy black with red-and-yellow shoulder patches they can show or hide. Females look nothing like them: streaky brown, like a big sparrow, with a peachy tint on the face. Look in marshes and wet fields, with males singing from cattails. The song sounds like "Conquereee". Males defend their nests fiercely and will dive-bomb much larger birds and even people.' WHERE latin_name = 'Agelaius phoeniceus';  -- Red-winged Blackbird
UPDATE birds SET description = 'Males are glossy black, with a purple shine on the head, a green shine on the body, and bright yellow eyes. Females are plain gray-brown, usually with darker eyes. Look in parking lots, farmland, towns, and meadows, walking along with its head bobbing like a pigeon. Listen for a short, creaky song. It is named for naturalist Thomas Brewer.' WHERE latin_name = 'Euphagus cyanocephalus';  -- Brewer's Blackbird
UPDATE birds SET description = 'Males are glossy black with a chocolate-brown head. Females are plain gray-brown. Look in fields, pastures, and at feeders. Cowbirds never build nests; females lay their eggs in the nests of more than 200 other species, and the hosts raise the chicks, a behavior called brood parasitism. They once followed bison herds across the plains, eating insects stirred up by the animals.' WHERE latin_name = 'Molothrus ater';  -- Brown-headed Cowbird
UPDATE birds SET description = 'A bright yellow warbler with beady black eyes and no strong markings. Males have rusty streaks on the chest; females are plainer. Look in willows and shrubs near water. Its cheerful song is often remembered as "sweet-sweet-sweet, I''m so sweet". When a cowbird lays an egg in its nest, it may build a new nest floor right over the top of the egg.' WHERE latin_name = 'Setophaga aestiva';  -- Northern Yellow Warbler
UPDATE birds SET description = 'A busy warbler with yellow patches on its rump and sides. They''re sometimes affectionately referred to as "butter-butts". Breeding males are gray with black streaks, and Utah''s birds usually have a yellow throat. Females are browner and softer in color, and both sexes turn duller in winter. Look in mountain evergreens in summer, and in valley trees during migration and winter.' WHERE latin_name = 'Setophaga coronata';  -- Yellow-rumped Warbler
UPDATE birds SET description = 'Males have a turquoise-blue head and back, a rusty-orange chest, a white belly, and white wing bars. Females are plain gray-brown, with a soft blue tint on the wings and tail and a warm tan chest. Look on brushy hillsides and along streams. It is named after the blue gemstone lapis lazuli. Young males build their songs by copying pieces from neighboring males.' WHERE latin_name = 'Passerina amoena';  -- Lazuli Bunting
UPDATE birds SET description = 'Males look tropical: a yellow body, black back and wings, and a flame-orange head. Females are olive-yellow with a grayish back and pale wing bars. Look in mountain evergreen forests in summer, and in valley trees during May migration. The male''s red head color comes from pigments in the insects it eats. Its song sounds like a hoarse American Robin, and its call is a dry "pit-er-ick".' WHERE latin_name = 'Piranga ludoviciana';  -- Western Tanager
UPDATE birds SET description = 'A songbird with a large, seed-cracking bill (grosbeak means "big beak"). Males have a black head, orange-cinnamon chest, and black-and-white wings. Females are streaky brown with a white eyebrow and tan chest. Look in oak canyons, along streams, and at feeders. Its song sounds like a robin''s but much sweeter. It is one of few birds that can eat toxic monarch butterflies.' WHERE latin_name = 'Pheucticus melanocephalus';  -- Black-headed Grosbeak
UPDATE birds SET description = 'A small warbler, olive-brown above with a bright yellow throat. Males wear a wide black mask bordered with white, like a little bandit. Females have no mask. Find it low in marshes and wet brush, where it is often easier to hear than see. Its song is a rolling "witchety-witchety-witchety", one of the easiest warbler songs for beginners to learn.' WHERE latin_name = 'Geothlypis trichas';  -- Common Yellowthroat
UPDATE birds SET description = 'A tiny warbler, olive above and bright yellow below, with a big dark eye. Males wear a neat black cap, like a small beret; females have an olive or faint dark cap. Look in mountain willow thickets in summer and in lowland shrubs during migration, flicking its tail as it hunts. It is named for Alexander Wilson, often called the father of American ornithology (study of birds).' WHERE latin_name = 'Cardellina pusilla';  -- Wilson's Warbler
UPDATE birds SET description = 'A plain olive-yellow warbler with faint streaks and a thin dark line through the eye. Sexes look similar, with females slightly more drab. Look in shrubs, aspens, and mountain thickets. Its song is a trill that fades and falls at the end. Do not count on the name to identify it: the orange crown patch stays hidden unless the bird raises its head feathers.' WHERE latin_name = 'Leiothlypis celata';  -- Orange Crowned Warbler
UPDATE birds SET description = 'A secretive warbler with an olive back and yellow belly. Males have a slate-gray hood that turns black on the chest, and bold white crescents above and below the eye. Females have a paler gray hood. Look low in dense, damp thickets and aspen stands, where it is hard to spot. John James Audubon named it for his Scottish colleague William MacGillivray.' WHERE latin_name = 'Geothlypis tolmiei';  -- MacGillivray's Warbler
UPDATE birds SET description = 'A chocolate-brown finch with a pink wash on its wings and belly, a black forehead, and a gray patch on the crown. Sexes look similar, with females slightly more drab. It nests on high peaks and snowfields, among the highest of any North American bird. In winter, flocks come down to mountain towns; ski-area feeders like those at Alta are a good place to look.' WHERE latin_name = 'Leucosticte tephrocotis';  -- Gray-crowned Rosy-Finch
UPDATE birds SET description = 'A drab, gray-brown flycatcher with a slightly peaked head, two pale wing bars, and no eye ring. Sexes look alike. Look in open forests, canyons, and streamside trees, on a bare branch. It flies out to snatch an insect, then often returns to the same perch. It is easiest to identify by voice: a burry, downward "pee-wee" repeated through the day.' WHERE latin_name = 'Contopus sordidulus';  -- Western Wood-Pewee
UPDATE birds SET description = 'A hummingbird of Utah''s mountains. Males are green above with a bright rose-magenta throat, and their wings make a loud, metallic trill you can hear before you see the bird. Females are green with a speckled throat and tan sides. Look in mountain meadows, aspen groves, and at feeders. On cold nights it enters torpor, slowing its body to save energy.' WHERE latin_name = 'Selasphorus platycercus';  -- Broad-tailed Hummingbird
UPDATE birds SET description = 'A plump, gray-brown ground bird with a scaly-looking belly and a comma-shaped plume on its head. Males have a black face outlined in white and a larger plume. Females are plainer and browner. Look in brushy areas, farmland, and yards, usually in a group called a covey. Listen for its call, which sounds like "chi-CA-go". It is California''s state bird.' WHERE latin_name = 'Callipepla californica';  -- California Quail
UPDATE birds SET description = 'A medium-sized hawk with a blue-gray back, rusty bars on the chest, red eyes, and a long, banded tail with a rounded tip. Sexes are colored alike, but females are about a third larger. Look in woods and neighborhoods, where it ambushes songbirds, sometimes at backyard feeders. It flies with a pattern of a few quick flaps and a glide.' WHERE latin_name = 'Astur cooperii';  -- Cooper's Hawk
UPDATE birds SET description = 'North America''s smallest falcon, about the size of a robin. Both sexes have two black "sideburn" stripes on a pale face. Males have a rusty back and slate-blue wings; females have rusty, barred wings. Look on wires and poles over open fields. It often hovers in the wind while hunting and bobs its tail when perched. Listen for a shrill "killy-killy-killy".' WHERE latin_name = 'Falco sparverius';  -- American Kestrel
UPDATE birds SET description = 'A small olive-green flycatcher with a yellowish belly, two pale wing bars, and a white, teardrop-shaped eye ring. Sexes look alike. Look along shady canyon streams and in cool forests. Males give a rising "pa-SEET" call. It nests on ledges, including under bridges and on buildings. Until 2023, it was split into two species: Pacific-slope and Cordilleran Flycatcher.' WHERE latin_name = 'Empidonax difficilis';  -- Western Flycatcher
UPDATE birds SET description = 'A slim hawk with a long tail, a white rump patch, and wings held in a V as it glides low over the ground. Males are pale gray, earning the nickname "gray ghost". Females are brown and streaked. Look over marshes and grasslands. Its owl-like, disc-shaped face helps it hear mice and voles hidden in the grass, a rare skill among hawks.' WHERE latin_name = 'Circus hudsonius';  -- Northern Harrier
UPDATE birds SET description = 'A huge raptor (bird of prey). Adults have a dark brown body, white head and tail, and a massive yellow bill. Females are larger than males. Young birds are mottled brown and take about five years to get a white head. Look near lakes and rivers, especially around the Great Salt Lake in winter. "Bald" comes from an old word for white, not a lack of feathers.' WHERE latin_name = 'Haliaeetus leucocephalus';  -- Bald Eagle
UPDATE birds SET description = 'A massive dark brown eagle with a golden sheen on the back of its head and neck, and feathers all the way down its legs. Females are larger than males. Young birds show white patches on the wings and tail. Look over mountains, canyons, and open sagebrush country. It hunts jackrabbits and other animals, and it can dive at more than 150 miles per hour.' WHERE latin_name = 'Aquila chrysaetos';  -- Golden Eagle
UPDATE birds SET description = 'A small gull. In summer it has a black hood, white crescents around the eye, a red bill, and a pink blush on the chest. In winter, the hood fades to a partial one. Sexes look alike. Look in marshes and fields, where it follows plows for insects, earning the old nickname "prairie dove". It is named for Arctic explorer Sir John Franklin.' WHERE latin_name = 'Leucophaeus pipixcan';  -- Franklin's Gull
UPDATE birds SET description = 'A tall blue-gray wader, up to about 4 feet, with a dagger-like yellow bill and a black plume over the eye. Sexes look alike. In flight, it folds its neck into an S-curve. Look along shorelines, marshes, and rivers, standing perfectly still to hunt fish. Though it looks huge, it weighs only about 5 pounds. It nests in treetop groups called rookeries.' WHERE latin_name = 'Ardea herodias';  -- Great Blue Heron
UPDATE birds SET description = 'A long-legged wading bird with a long, down-curved bill. From afar it looks black, but up close it is deep chestnut with shiny green and purple wings. In breeding season, a white border surrounds its bare red face. Sexes look alike, though males are larger. Look in marshes and flooded fields, especially around the Great Salt Lake, home to large nesting colonies.' WHERE latin_name = 'Plegadis chihi';  -- White-faced Ibis
UPDATE birds SET description = 'A subtle duck that rewards a closer look. Males look plain gray from afar, but up close their feathers show fine black-and-gray patterns, with a black rear end. Females are mottled brown, with an orange-edged bill. Both sexes have a white wing patch that shows in flight. Look on marshes, ponds, and lakes, tipping forward to feed on underwater plants.' WHERE latin_name = 'Mareca strepera';  -- Gadwall
UPDATE birds SET description = 'A small duck of the West. Males are a rich cinnamon-red with bright red eyes. Females are mottled brown and hard to tell from other small female ducks. Both have a pale blue wing patch that shows in flight. Look in shallow marshes, especially around the Great Salt Lake. Its broad bill works like a strainer, filtering tiny food from the water.' WHERE latin_name = 'Spatula cyanoptera';  -- Cinnamon Teal
UPDATE birds SET description = 'A small, compact duck with a stiff tail often held straight up. Breeding males are chestnut with a sky-blue bill, black cap, and white cheek; in winter they turn gray-brown. Females are brown with a dark line across a pale cheek. Look on ponds and marshes. In courtship, males drum their bills against their chests, making bubbles on the water.' WHERE latin_name = 'Oxyura jamaicensis';  -- Ruddy Duck
UPDATE birds SET description = 'A small white goose with black wingtips and a stubby pink bill. Sexes look alike. It resembles the larger Snow Goose, but lacks the Snow Goose''s dark "grin patch" along the bill. Look for it in farm fields and wetlands during migration; it nests in the Arctic. It is named for Bernard Ross, a Hudson''s Bay Company trader.' WHERE latin_name = 'Anser rossii';  -- Ross's Goose
UPDATE birds SET description = 'A plump, slaty-black waterbird with a white bill and red eyes. Sexes look alike. It looks like a duck, but it is related to rails and cranes. Instead of webbed feet, it has long toes with flaps called lobes. Look on ponds, marshes, and park lakes, often in big, noisy groups. Its chicks are surprisingly colorful, with orange-and-red plumes on the head.' WHERE latin_name = 'Fulica americana';  -- American Coot
UPDATE birds SET description = 'Males have a white stripe on the forehead, a green swoosh behind the eye, and pinkish-brown sides. That white stripe gave it the old nickname "baldpate". Females are warm brown with a grayer head. Both have a small blue-gray bill with a black tip. Look on marshes and lakes, and for groups grazing on grassy fields. Males give a whistle like a squeaky toy.' WHERE latin_name = 'Mareca americana';  -- American Wigeon
UPDATE birds SET description = 'A large, powerful owl with yellow eyes, a white throat, and mottled brown feathers. The "horns" are just feather tufts, not ears. Sexes look alike, though females are larger. Look in forests, deserts, and city parks. Its deep hoots are often remembered as "Who''s awake? Me too". It nests in late winter and hunts animals as large as skunks.' WHERE latin_name = 'Bubo virginianus';  -- Great Horned Owl
UPDATE birds SET description = 'Not a hawk at all. This slim, mottled gray-brown bird has long, pointed wings with white bars sometimes referred to as "bracelets", and a tiny bill that opens into a huge mouth for catching insects. Males have a white throat and tail band; females have a tan throat and no tail band. Look at dusk over towns and open country. Listen for a nasal "peent".' WHERE latin_name = 'Chordeiles minor';  -- Common Nighthawk
UPDATE birds SET description = 'A small, stocky owl with gray-brown streaks, yellow eyes, and short ear tufts. Its feathers look just like tree bark. Sexes look alike, with females slightly larger. Look in streamside woods and older neighborhoods, where it nests in tree holes and nest boxes. Despite its name, it doesn''t really screech. Its call is a series of toots that speed up, like a bouncing ball.' WHERE latin_name = 'Megascops kennicottii';  -- Western Screech Owl
UPDATE birds SET description = 'A pale owl with a heart-shaped white face and dark eyes. Its back is golden and gray, and its underparts are whitish. Females are often more spotted and rusty below, males whiter. Look around barns, farms, and open fields at night. It does not hoot. Instead, it gives a long, raspy scream. Its hearing is so good that it can catch mice in total darkness.' WHERE latin_name = 'Tyto furcata';  -- American Barn Owl
UPDATE birds SET description = 'A pale, sandy-gray dove with a black half-collar on the back of its neck and a square tail with white corners. Sexes look alike. Look on wires and rooftops in towns and on farms. Its three-part coo sounds like "u-NI-ted". Brought to the Bahamas in the 1970s, it reached Florida and then rapidly spread across much of North America.' WHERE latin_name = 'Streptopelia decaocto';  -- Eurasian Collared Dove
UPDATE birds SET description = 'A huge ground bird with dark, shimmering bronze feathers. Males have a bare red-and-blue head, a "beard" of bristles on the chest, a fanned tail, and a loud gobble. Females are smaller and browner. Look along forest edges and in oak foothills. They can fly short distances and sleep in trees. Ben Franklin once called the turkey more respectable than the Bald Eagle.' WHERE latin_name = 'Meleagris gallopavo';  -- Wild Turkey
UPDATE birds SET description = 'A large fish-eating raptor (bird of prey), dark brown above and white below, with a dark stripe through the eye. In flight, its wings bend in an "M" shape. Females are larger, often with a darker necklace. Look over lakes, rivers, and reservoirs, and for big stick nests on platforms. It hovers, then plunges feet-first and carries its catch headfirst, like a torpedo.' WHERE latin_name = 'Pandion haliaetus';  -- Osprey
UPDATE birds SET description = 'A tiny, feisty hummingbird. Males are a bright rust-orange on the back and sides, with a glowing red-orange throat. Females are green above with rusty sides and tail, and a small orange throat spot. Look in mountain meadows and at feeders in mid to late summer, as it passes through Utah. Some travel almost 4,000 miles from Alaska to Mexico, chasing off much larger birds along the way.' WHERE latin_name = 'Selasphorus rufus';  -- Rufous Hummingbird
UPDATE birds SET description = 'A slim gray thrush with a white eye ring, white outer tail feathers, and tan wing patches that show in flight. Sexes look alike. Look at the tops of mountain evergreens in summer and in juniper woodlands in winter, where it fiercely defends berry trees from other birds. Its long, warbling song can be heard even on cold winter days.' WHERE latin_name = 'Myadestes townsendi';  -- Townsend's Solitaire
UPDATE birds SET description = 'A stocky, slate-gray bird with a short tail that constantly bobs up and down, or "dips". White eyelids flash when it blinks. Sexes look alike. Look along fast, clear mountain streams, on rocks in the middle of the current. It is North America''s only truly aquatic songbird, walking and swimming underwater to catch insects. Its formal name is American Dipper.' WHERE latin_name = 'Cinclus mexicanus';  -- Dipper
UPDATE birds SET description = 'A small, plain brown bird with fine dark bars on its wings and tail, which is often held up. Sexes look alike. Look in yards, woodland edges, and aspen groves. Its loud, bubbling song seems too big for its body. Males stuff sticks into several holes, and females pick one to finish. Wrens have nested in old boots, mailboxes, and even parked cars.' WHERE latin_name = 'Troglodytes aedon';  -- Northern House Wren
UPDATE birds SET description = 'A larger, grayer cousin of the Cedar Waxwing, with a crest, a black mask, a yellow tail tip, and a rusty patch under the tail. Its wings show white and yellow markings plus waxy red tips. Sexes look nearly alike. Nesting in far northern forests, flocks wander into Utah some winters to strip berry trees. "Bohemian" refers to its wandering lifestyle.' WHERE latin_name = 'Bombycilla garrulus';  -- Bohemian Waxwing
UPDATE birds SET description = 'Males look entirely deep blue, though the color comes from how feathers scatter light, not from blue pigment. Females are plain brown. Look along brushy edges and streams; it is uncommon in Utah and sometimes pairs with Lazuli Buntings. Its song is made of paired phrases, remembered as "fire-fire, where-where, here-here". It navigates at night using the stars.' WHERE latin_name = 'Passerina cyanea';  -- Indigo Bunting
UPDATE birds SET description = 'A large sparrow with a rusty cap, a white throat, a gray chest, and olive-green wings and tail. Sexes look alike. Look in sagebrush and on mountain shrub slopes, usually low to the ground. Listen for a catlike "mew" and rustling as it scratches with both feet. If startled from its nest, it may run away along the ground like a mouse.' WHERE latin_name = 'Pipilo chlorurus';  -- Green-tailed Towhee
UPDATE birds SET description = 'A robin-sized, gray songbird with a black mask, black wings with white patches, and a small hooked bill. Sexes look alike. Look on wires and fences in open country with scattered shrubs. Nicknamed the "butcher bird", it hunts insects, lizards, and mice, then sticks them on thorns or barbed wire to eat later. "Loggerhead" refers to its large, blocky head.' WHERE latin_name = 'Lanius ludovicianus';  -- Loggerhead Shrike
COMMIT;

-- Step 3: check the result. Expect 100 filled, 0 missing.
SELECT COUNT(description) AS filled, SUM(description IS NULL) AS missing FROM birds;